// Menu IDs
enum
{
   ID_REMOVELINES = wxID_HIGHEST,
   ID_EXECUTE,
};

CCommanderHistory::CCommanderHistory(
    CCommander *    Parent,
    wxWindowID      Id
    ) : wxRichTextCtrl(
        Parent,
        Id,
        wxEmptyString,
        wxDefaultPosition,
        wxDefaultSize,
        wxRE_READONLY | wxWANTS_CHARS)
{
    // The background color should be light gray to indicate that this
    // is a read-only control.
    SetBackgroundColour(wxSystemSettings::GetColour(wxSYS_COLOUR_3DLIGHT));

    // Nothing that we write to the control should be undoable by
    // the user.
    BeginSuppressUndo();

    // Configure the keyboard shortcuts.
    static const ACCELERATORITEM keyboardShortcuts[] = {
        // Enter does the same as pressing the Execute button.
        {wxACCEL_NORMAL, WXK_RETURN, ID_EXECUTE},

        // F1 brings up context-sensitive help
        {wxACCEL_NORMAL, WXK_F1,   wxID_HELP_INDEX},

        // Ctrl+C copies the select to the clipboard
        {wxACCEL_CTRL,  'C',       wxID_COPY},

        // Note that navigation keyboard shortcuts could be implemented
        // as acelerators, are instead implemented within OnKeyDown.
    };
    SetAccelerators(this, keyboardShortcuts, ARRAYSIZE(keyboardShortcuts));
}

CCommander * CCommanderHistory::GetCommander() const
{
    return static_cast<CCommander*>(GetParent());
}

bool CCommanderHistory::IsCursorAtBottom() const
{
    long caretPosition = GetCaretPosition();
    long lastPosition  = GetLastPosition();

    return lastPosition <= caretPosition + 1;
}

void CCommanderHistory::CopyCurrentLineToCommanderInput() const
{
    wxRichTextLine * line = GetVisibleLineForCaretPosition(GetCaretPosition());
    if (line != NULL)
    {
        wxRichTextParagraph* paragraph = GetBuffer().GetParagraphForLine(line);
        if (paragraph != NULL)
        {
            wxRichTextRange range(paragraph->GetRange());

            const wxString & text = GetRange(range.GetStart(), range.GetEnd());

            GetCommander()->GetInput()->SetText(text);
        }
    }
}

// Make sure that the line with caret it visible and copy
// the contents of that line to the commander's input box.
void CCommanderHistory::ShowCurrentLine(int KeyCode)
{
    ScrollIntoView(GetCaretPosition(), KeyCode);
    CopyCurrentLineToCommanderInput();
}


void CCommanderHistory::OnContextHelp(wxCommandEvent& Event)
{
    ContextHelp(GetStringSelection());
}

void CCommanderHistory::OnExecute(wxCommandEvent & Event)
{
    GetCommander()->GiveControlToInputBox();
    GetCommander()->Execute();
}

void CCommanderHistory::OnKeyDown(wxKeyEvent& Event)
{
    int keyCode = Event.GetKeyCode();

    int  flags      = (Event.ShiftDown()) ? wxRICHTEXT_SHIFT_DOWN : 0;
    bool movedCaret = false;

#if defined(__WXGTK__)
    // On GTK+, navigation by numpad while the Shift key is held down
    // generates events as if numlock were on, instead of the navigation
    // code.  To account for this, we re-map the key codes back to
    // what they should have been.  This, assumes that, for example,
    // Shift+NumPad2 is otherwise impossible and could only have been
    // generated by WXK_SHIFT + WXK_NUMPAD_DOWN.  It also may assume
    // a particular keyboard layout.
    if (Event.ShiftDown())
    {
        switch (keyCode)
        {
        case WXK_NUMPAD1:
            keyCode = WXK_NUMPAD_END;
            break;

        case WXK_NUMPAD2:
            keyCode = WXK_NUMPAD_DOWN;
            break;

        case WXK_NUMPAD3:
            keyCode = WXK_NUMPAD_PAGEDOWN;
            break;

        case WXK_NUMPAD4:
            keyCode = WXK_NUMPAD_LEFT;
            break;

        case WXK_NUMPAD6:
            keyCode = WXK_NUMPAD_RIGHT;
            break;

        case WXK_NUMPAD7:
            keyCode = WXK_NUMPAD_HOME;
            break;

        case WXK_NUMPAD8:
            keyCode = WXK_NUMPAD_UP;
            break;

        case WXK_NUMPAD9:
            keyCode = WXK_NUMPAD_PAGEUP;
            break;
        }
    }
#endif

    switch (keyCode)
    {
    case WXK_HOME:
    case WXK_NUMPAD_HOME:
        if (Event.ControlDown())
        {
            // CTRL+HOME scrolls to the top
            MoveHome(flags);
            movedCaret = true;
        }
        else
        {
            GetCommander()->ProcessKeyDownEventAtInputControl(Event);
        }
        break;


    case WXK_END:
    case WXK_NUMPAD_END:
        if (Event.ControlDown())
        {
            // CTRL+END scrolls to the bottom
            MoveEnd(flags);
            movedCaret = true;
        }
        else
        {
            GetCommander()->ProcessKeyDownEventAtInputControl(Event);
        }
        break;


    case WXK_PAGEUP:
    case WXK_NUMPAD_PAGEUP:
        // Page Up moves one screen up
        PageUp(1, flags);
        movedCaret = true;
        break;


    case WXK_PAGEDOWN:
    case WXK_NUMPAD_PAGEDOWN:
        // Page Down moves one screen down
        PageDown(1, flags);
        movedCaret = true;
        break;


    case WXK_DOWN:
    case WXK_NUMPAD_DOWN:
        // If the caret is at the bottom of the history box,
        // then going down from means moving to the input box.
        // We don't do this when extending a selection, since
        // that would clear the selection, when the user is
        // probably trying to select everything from a certian
        // point onward.
        if (!Event.ShiftDown() && IsCursorAtBottom())
        {
            // Clear the selection to be consistent with MSWLogo.
            // (This isn't quite right; MSWLogo merely *hid* the
            // selection and it re-appeared when the commander
            // history regained focus.)
            SelectNone();

            // Give focus to the commander's input box.
            GetCommander()->GiveControlToInputBox();
        }
        else
        {
            // Move down one line.
            // Note that we do this even when Ctrl is pressed,
            // because the default behavior of Ctrl+Down is to
            // move to the end of the "paragraph", which would
            // move to the end of the line, not down one line.
            MoveDown(1, flags);
            movedCaret = true;
        }
        break;


    case WXK_UP:
    case WXK_NUMPAD_UP:
        MoveUp(1, flags);
        movedCaret = true;
        break;


    case WXK_LEFT:
    case WXK_NUMPAD_LEFT:
        if (Event.ControlDown())
        {
            WordLeft(1, flags);
        }
        else
        {
            MoveLeft(1, flags);
        }
        movedCaret = true;
        break;


    case WXK_TAB:
        if (Event.ShiftDown())
        {
            // Shift+Tab means navigate backward.
            Navigate(wxNavigationKeyEvent::IsBackward);
        }
        else
        {
            // Tab means navigate forward.
            Navigate(wxNavigationKeyEvent::IsForward);
        }
        break;


    default:
        if (CCommanderInput::WantsKeyEvent(keyCode))
        {
            GetCommander()->ProcessKeyDownEventAtInputControl(Event);
        }
        else
        {
            // default processing
            Event.Skip();
        }
    }

    if (movedCaret)
    {
        ShowCurrentLine(keyCode);
    }
}

void CCommanderHistory::MoveToTop()
{
    MoveHome(0);
    ShowCurrentLine(WXK_HOME);
}

void CCommanderHistory::SelectAllToTop()
{
    MoveEnd(0);
    MoveHome(wxRICHTEXT_SHIFT_DOWN);
    ShowCurrentLine(WXK_HOME);
}

void CCommanderHistory::MoveToOnePageUpFromBottom()
{
    MoveEnd(0);
    PageUp(1, 0);
    ShowCurrentLine(WXK_PAGEUP);
}

void CCommanderHistory::SelectToOnePageUpFromBottom()
{
    MoveEnd(0);
    PageUp(1, wxRICHTEXT_SHIFT_DOWN);
    ShowCurrentLine(WXK_PAGEUP);
}

void CCommanderHistory::ScrollToBottom()
{
    long lastPosition = GetLastPosition();
    ShowPosition(lastPosition);
}

void CCommanderHistory::OnLeftMouseButtonDown(wxMouseEvent& Event)
{
    // Have the base class process the mouse click so that
    // the cursor will be moved to the location of the click.
    OnLeftClick(Event);
    OnLeftUp(Event);

    // On a single click, the contents of the current line
    // gets copied to the commander's input box.
    CopyCurrentLineToCommanderInput();

    // Continue with the default processing for the event.
    Event.Skip();
}

void CCommanderHistory::OnLeftMouseButtonDoubleClick(wxMouseEvent& Event)
{
    // On a double-click, the contents of the current line are executed.
    CopyCurrentLineToCommanderInput();
    GetCommander()->GiveControlToInputBox();
    GetCommander()->Execute();

    // Don't call Event.Skip() because GetCommander()->Execute can run
    // TEXTSCREEN, which would delete this control.  Therefore we cannot
    // safely do any further processing on this control.
}

// Removes the selected lines, which are assumed to be whole lines.
void CCommanderHistory::OnRemoveSelectedLines(wxCommandEvent& Event)
{
    wxTextPos start;
    wxTextPos end;
    GetSelection(&start, &end);

    if (start != 0 &&                            // not the start of the buffer
        GetRange(start - 1, start)[0] != '\n' && // not on the start of a line
        GetRange(start, start + 1)[0] == '\n')   // on the end of a line
    {
        // The selection is not at the start of a line, but
        // it includes the newline from the previous line.
        // This is a natural way to select a line if the user
        // moves the mouse up one line, instead of to the left
        // end of the top line.
        // In this case, we want to do what the user expects,
        // which is not to delete the newline character, thereby
        // joining the lines before and after the selection onto
        // the same line, but instead, remove the lines which are
        // selected.
        start++;
    }

    if (GetRange(end - 1, end)[0] != '\n' && // not immediately after a newline
        GetRange(end, end + 1)[0] == '\n')   // at a newline
    {
        // The selection does not continue through the
        // end of the line, but it ends at a line.
        // This a natural way for the user to select
        // a line, but deleting the selection will
        // not do what they want.
        end++;
    }

    // Fix the selection to be whole lines.
    SetSelection(start, end);

    // Remove the selected lines.
    DeleteSelectedContent();
}

void CCommanderHistory::OnUpdateRemoveSelectedLines(wxUpdateUIEvent& Event)
{
    if (!HasSelection())
    {
        Event.Enable(false);
    }
    else
    {
        // Allow the user to remove selected lines only if they have
        // selected whole lines
        wxTextPos start;
        wxTextPos end;
        GetSelection(&start, &end);

        // Check if the selection's start is at the start of the line
        bool selectionStartIsAtStartOfLine;
        if (start == 0                            || // the start of the buffer
            GetRange(start - 1, start)[0] == '\n' || // the start of a line
            GetRange(start, start + 1)[0] == '\n')   // at the end of a line
        {
            selectionStartIsAtStartOfLine = true;
        }
        else
        {
            selectionStartIsAtStartOfLine = false;
        }

        // Check if the selection's end is at the end of the line
        bool selectionEndIsAtEndOfLine;
        if (GetRange(end - 1, end)[0] == '\n' || // just after a newline
            GetRange(end, end + 1)[0] == '\n')   // at a newline
        {
            selectionEndIsAtEndOfLine = true;
        }
        else
        {
            selectionEndIsAtEndOfLine = false;
        }

        Event.Enable(selectionStartIsAtStartOfLine && selectionEndIsAtEndOfLine);
    }
}

void CCommanderHistory::OnContextMenu(wxContextMenuEvent& Event)
{
    // The history only supports a limited set of editing
    static const MENUITEM contextMenuItems[] = {
        {g_LOCALIZED_POPUP_COPY,        wxID_COPY},
        {g_LOCALIZED_POPUP_REMOVELINES, ID_REMOVELINES},
        {g_LOCALIZED_POPUP_SELECTALL,   wxID_SELECTALL},
        {0},
        {g_LOCALIZED_POPUP_HELP,        wxID_HELP_INDEX},
    };

    wxMenu menu;
    FillMenu(&menu, contextMenuItems, ARRAYSIZE(contextMenuItems));

    PopupMenu(&menu);
}

void CCommanderHistory::OnSetFocus(wxFocusEvent & Event)
{
    // When the control gets keyboard focus, copy the current selection
    // to the commander input control.
    CopyCurrentLineToCommanderInput();
    Event.Skip();
}

